mapper.select:
SELECT

FROM distribution_order AS distribution_order

    AND distribution_order.del_flag = '0'

        AND distribution_order.biz_order_id = #{query.bizOrderId}


        AND distribution_order.buyer_user_id = #{query.buyerUserId}


        AND distribution_order.distributor_user_id = #{query.distributorUserId}


        AND distribution_order.status = #{query.status}


ORDER BY distribution_order.create_time DESC
